-- Additive SEO, GEO visibility, redirects, audit, and media metadata.
ALTER TABLE "Project" ADD COLUMN "ogTitle" TEXT, ADD COLUMN "ogDescription" TEXT, ADD COLUMN "noFollow" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "includeSitemap" BOOLEAN NOT NULL DEFAULT true, ADD COLUMN "focusTopic" TEXT, ADD COLUMN "publicModifiedAt" TIMESTAMP(3), ADD COLUMN "relatedProjectIds" TEXT[] DEFAULT ARRAY[]::TEXT[], ADD COLUMN "relatedContentIds" TEXT[] DEFAULT ARRAY[]::TEXT[];
ALTER TABLE "Content" ADD COLUMN "ogTitle" TEXT, ADD COLUMN "ogDescription" TEXT, ADD COLUMN "ogImage" TEXT, ADD COLUMN "canonicalUrl" TEXT, ADD COLUMN "noIndex" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "noFollow" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "includeSitemap" BOOLEAN NOT NULL DEFAULT true, ADD COLUMN "focusTopic" TEXT, ADD COLUMN "references" JSONB NOT NULL DEFAULT '[]', ADD COLUMN "relatedProjectIds" TEXT[] DEFAULT ARRAY[]::TEXT[], ADD COLUMN "relatedContentIds" TEXT[] DEFAULT ARRAY[]::TEXT[], ADD COLUMN "publicModifiedAt" TIMESTAMP(3);
ALTER TABLE "Media" ADD COLUMN "caption" TEXT, ADD COLUMN "creator" TEXT, ADD COLUMN "credit" TEXT, ADD COLUMN "decorative" BOOLEAN NOT NULL DEFAULT false;

CREATE TABLE "SeoSettings" ("id" TEXT NOT NULL,"siteName" TEXT NOT NULL DEFAULT 'Mahmudul Hassan',"defaultTitle" TEXT,"titleTemplate" TEXT NOT NULL DEFAULT '%s — Mahmudul Hassan',"defaultDescription" TEXT,"defaultOgTitle" TEXT,"defaultOgDescription" TEXT,"defaultOgImage" TEXT,"twitterCard" TEXT NOT NULL DEFAULT 'summary_large_image',"canonicalOrigin" TEXT,"defaultIndex" BOOLEAN NOT NULL DEFAULT true,"defaultFollow" BOOLEAN NOT NULL DEFAULT true,"siteLanguage" TEXT NOT NULL DEFAULT 'en',"siteLocale" TEXT NOT NULL DEFAULT 'en_US',"googleVerification" TEXT,"bingVerification" TEXT,"crawlerConfig" JSONB NOT NULL DEFAULT '{}',"socialProfiles" TEXT[] DEFAULT ARRAY[]::TEXT[],"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "SeoSettings_pkey" PRIMARY KEY ("id"));
CREATE TABLE "EntityProfile" ("id" TEXT NOT NULL,"publicName" TEXT NOT NULL DEFAULT 'Mahmudul Hassan',"alternateName" TEXT,"professionalTitle" TEXT,"shortBio" TEXT,"longBio" TEXT,"portrait" TEXT,"profilePath" TEXT NOT NULL DEFAULT '/#about',"location" TEXT,"expertise" TEXT[] DEFAULT ARRAY[]::TEXT[],"services" TEXT[] DEFAULT ARRAY[]::TEXT[],"socialProfiles" TEXT[] DEFAULT ARRAY[]::TEXT[],"contactPath" TEXT NOT NULL DEFAULT '/#contact',"stableIdentifier" TEXT NOT NULL DEFAULT 'person',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "EntityProfile_pkey" PRIMARY KEY ("id"));
CREATE TABLE "RedirectRule" ("id" TEXT NOT NULL,"sourcePath" TEXT NOT NULL,"destination" TEXT NOT NULL,"statusCode" INTEGER NOT NULL DEFAULT 301,"enabled" BOOLEAN NOT NULL DEFAULT true,"reason" TEXT,"hitCount" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "RedirectRule_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SeoAuditIssue" ("id" TEXT NOT NULL,"pageType" TEXT NOT NULL,"pageId" TEXT,"url" TEXT NOT NULL,"code" TEXT NOT NULL,"severity" TEXT NOT NULL,"message" TEXT NOT NULL,"details" JSONB NOT NULL DEFAULT '{}',"resolved" BOOLEAN NOT NULL DEFAULT false,"checkedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SeoAuditIssue_pkey" PRIMARY KEY ("id"));
CREATE TABLE "IndexNowSubmission" ("id" TEXT NOT NULL,"url" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'QUEUED',"responseCode" INTEGER,"error" TEXT,"attempts" INTEGER NOT NULL DEFAULT 0,"submittedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "IndexNowSubmission_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "RedirectRule_sourcePath_key" ON "RedirectRule"("sourcePath");
CREATE INDEX "RedirectRule_enabled_sourcePath_idx" ON "RedirectRule"("enabled","sourcePath");
CREATE INDEX "SeoAuditIssue_severity_resolved_idx" ON "SeoAuditIssue"("severity","resolved");
CREATE INDEX "SeoAuditIssue_pageType_pageId_idx" ON "SeoAuditIssue"("pageType","pageId");
CREATE INDEX "IndexNowSubmission_url_createdAt_idx" ON "IndexNowSubmission"("url","createdAt");
CREATE INDEX "IndexNowSubmission_status_createdAt_idx" ON "IndexNowSubmission"("status","createdAt");
